import React, { useState, useEffect } from "react";
import { checkout } from "../api/api";
import { useNavigate } from "react-router-dom";
import jwtDecode from "jwt-decode";

export default function Checkout() {
  const [total, setTotal] = useState(null);
  const [user, setUser] = useState({ name: "", email: "" });
  const [billingTime, setBillingTime] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    // Decode token to extract user info (assuming JWT has name & email)
    const token = localStorage.getItem("token");
    if (token) {
      try {
        const decoded = jwtDecode(token);
        setUser({
          name: decoded.name || "Unknown User",
          email: decoded.email || "No email found",
        });
      } catch (err) {
        console.error("Invalid token:", err);
      }
    }

    // Set current billing time
    const now = new Date();
    const formattedTime = now.toLocaleString("en-IN", {
      dateStyle: "full",
      timeStyle: "short",
    });
    setBillingTime(formattedTime);
  }, []);

  const handleCheckout = async () => {
    try {
      const res = await checkout();
      setTotal(res.data.total);
    } catch {
      alert("Checkout failed");
    }
  };

  const handleConfirm = () => {
    alert("Payment successful!");
    navigate("/");
  };

  return (
    <div className="checkout-container">
      <div className="checkout-card">
        <h3 className="text-center mb-4">🧾 Checkout Summary</h3>

        <div className="checkout-details mb-4">
          <p><strong>👤 Name:</strong> {user.name}</p>
          <p><strong>📧 Email:</strong> {user.email}</p>
          <p><strong>🕒 Billing Time:</strong> {billingTime}</p>
        </div>

        {!total ? (
          <button className="btn btn-success w-100" onClick={handleCheckout}>
            Generate Final Bill
          </button>
        ) : (
          <div className="checkout-total text-center">
            <h4 className="my-3">💰 Total Payable: ₹{total}</h4>
            <button className="btn btn-primary w-100" onClick={handleConfirm}>
              Confirm Payment
            </button>
          </div>
        )}
      </div>
    </div>
  );
}
